import React, { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import "./BuyHouseList.css";

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "—";
  const v = Number(n);
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function BuyHouseList() {
  const [searchParams] = useSearchParams();
  const cityFilter = searchParams.get('city'); // Get city from URL
  
  const [houses, setHouses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function fetchHouses() {
      try {
        setLoading(true);
        let url = `${process.env.REACT_APP_BACKEND_URL}/buy/houses`;
        
        // If city filter exists, use search endpoint
        if (cityFilter && cityFilter.trim()) {
          url = `${process.env.REACT_APP_BACKEND_URL}/buy/search?city=${encodeURIComponent(cityFilter.trim())}`;
        }
        
        console.log("Fetching from:", url); // Debug log
        
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const data = await response.json();
        console.log("Received data:", data); // Debug log
        
        // Ensure data is an array
        const houseArray = Array.isArray(data) ? data : [];
        
        // Client-side filtering as backup (case-insensitive)
        let filteredHouses = houseArray;
        if (cityFilter && cityFilter.trim()) {
          const searchCity = cityFilter.trim().toLowerCase();
          filteredHouses = houseArray.filter(house => {
            const houseCity = (house.city || "").toLowerCase();
            const houseLocation = (house.location || "").toLowerCase();
            return houseCity.includes(searchCity) || houseLocation.includes(searchCity);
          });
        }
        
        setHouses(filteredHouses);
        setError("");
      } catch (err) {
        console.error("Error fetching houses:", err);
        setError("Failed to load houses. Please try again.");
        setHouses([]);
      } finally {
        setLoading(false);
      }
    }

    fetchHouses();
  }, [cityFilter]); // Re-fetch when city filter changes

  if (loading) {
    return (
      <div className="buy-house-container">
        <div className="loading-message">Loading houses...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="buy-house-container">
        <div className="error-message">{error}</div>
      </div>
    );
  }

  return (
    <div className="buy-house-container">
      <div className="buy-house-header">
        <h1>Available Houses for Sale</h1>
        {cityFilter && (
          <p className="filter-info">
            Showing results for: <strong>{cityFilter}</strong>
            <a href="/buy-house" className="clear-filter">Clear Filter</a>
          </p>
        )}
      </div>

      {houses.length === 0 ? (
        <div className="no-results">
          <h2>No houses found</h2>
          {cityFilter && <p>No houses available in "{cityFilter}". Try a different city.</p>}
          {!cityFilter && <p>No houses are currently listed.</p>}
        </div>
      ) : (
        <div className="house-list">
          {houses.map((house) => (
            <div key={house.id} className="house-card">
              <div className="house-image-wrapper">
                {house.images && house.images.length > 0 ? (
                  <img
                    src={`${process.env.REACT_APP_BACKEND_URL}/image/${house.images[0]}`}
                    alt={house.title || "House"}
                    className="house-image"
                  />
                ) : (
                  <div className="house-image-placeholder">No Image</div>
                )}
                <span className="house-badge">Resale</span>
              </div>

              <div className="house-details">
                <h3 className="house-title">{house.title || "Independent House"}</h3>
                <div className="house-price">{formatCurrencyINR(house.actualPrice)}</div>

                <div className="house-specs">
                  <span>{house.builtUpArea || "—"} sq.ft</span>
                  <span>{house.numBedrooms || "—"} Beds</span>
                  <span>{house.numBathrooms || "—"} Baths</span>
                </div>

                <div className="house-location">
                  📍 {house.location || house.city || "Location not specified"}
                </div>

                <div className="house-actions">
                  <button className="btn-contact">Contact</button>
                  <button className="btn-predict">Predict</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
